function validateCommit(message) {
  const validTypes = new Set(['feat', 'fix', 'docs', 'style', 'refactor', 'test', 'chore', 'perf', 'ci', 'build']);

  const result = {
    valid: true,
    type: null,
    scope: null,
    description: null,
    breaking: false,
    errors: []
  };

  const firstLine = message.split('\n')[0];
  const match = firstLine.match(/^(\w+)(\(([a-z0-9]+)\))?(!)?:\s(.+)$/);

  if (!match) {
    result.valid = false;
    result.errors.push('Invalid commit format');
    return result;
  }

  const [, type, , scope, bang, description] = match;
  result.type = type;
  result.scope = scope || null;
  result.description = description;
  result.breaking = bang === '!' || message.includes('BREAKING CHANGE:');

  if (!validTypes.has(type)) {
    result.errors.push(`Invalid type: ${type}`);
  }
  if (description && description[0] === description[0].toUpperCase() && description[0] !== description[0].toLowerCase()) {
    result.errors.push('Description must start with lowercase');
  }
  if (description && description.endsWith('.')) {
    result.errors.push('Description must not end with period');
  }
  if (description && description.length > 72) {
    result.errors.push('Description exceeds 72 characters');
  }

  result.valid = result.errors.length === 0;
  return result;
}
